"""Collection-level finding aid for an explicitly editorial digital catalogue."""
from html import escape
from collections import Counter
import csv,io,json,urllib.parse
E=lambda x:escape(str(x or ''),quote=True)

def build_finding_aid(records,programmes,write,layout):
 groups=list(dict.fromkeys(r['collection'] for r in records));dates=sorted(r['date'][:4] for r in records);languages=sorted({r.get('language') or 'Not supplied' for r in records});copies=[r for r in records if r.get('reading_copy')];pages=sum(r.get('page_count',0) for r in records);totalbytes=sum(f.get('size',0) for r in records for f in r.get('files',[]))
 content=f'''<div class="page-head"><div class="breadcrumb"><a href="index.html">Archive</a> / Finding aid</div><div class="eyebrow">Collection-level guide / Local editorial arrangement</div><h1>Finding aid</h1><p>Museum of One Digital Archive Library — Selected published corpus</p></div><section class="finding-summary"><dl class="context-register"><div><dt>Title</dt><dd>Selected publications and research records of Museum of One</dd></div><div><dt>Creator context</dt><dd>Dorian Vale / Museum of One, as documented by the individual source records</dd></div><div><dt>Dates represented</dt><dd>{dates[0]}–{dates[-1]} · Source publication dates, with precision retained at item level</dd></div><div><dt>Extent</dt><dd>{len(records)} described items · {len(groups)} editorial groupings · {len(copies)} digital reading copies<br>{pages:,} PDF file pages across the selected copies · {totalbytes:,} bytes of source files</dd></div><div><dt>Language values</dt><dd>{E(', '.join(languages))} · As supplied in the catalogue; not independently language-tagged</dd></div><div><dt>Level of description</dt><dd>Collection-level guide to a selected digital catalogue</dd></div></dl></section><nav class="record-tabs" aria-label="Finding aid sections"><a href="#scope">Scope & content ↓</a><a href="#arrangement">Arrangement ↓</a><a href="#access">Access & use ↓</a><a href="#inventory">Item inventory ↓</a></nav><div class="finding-text"><section id="scope"><h2>Scope & content</h2><p>This selected catalogue describes books, critical essays, working papers, diagnostic materials and research publications associated with Museum of One and Dorian Vale. Each item retains its source-specific description, dates, identifiers, rights and version context.</p><p>The catalogue was assembled from public Zenodo records and corroborated against institutional work pages. It is not a complete institutional archive or a recovered export of the former Omeka collection. Original deposit metadata remains available as a source snapshot.</p></section><section id="arrangement"><h2>System of arrangement</h2><p>The three browsing groupings below are a local editorial arrangement. They do not assert an original fonds, a series created by the repository, or a physical storage order. Reference codes MOO-CAT-001 onward identify local item descriptions and remain stable as the catalogue grows.</p><p>Research programmes provide contextual relationships where institutional work pages document them. They are distinct from the browsing arrangement and retain their own development stages.</p></section><section id="access"><h2>Conditions of access & use</h2><p>Byte-identical access copies support the in-site document reader. Zenodo remains the source of record. A matching source checksum confirms file identity; it does not establish legal deposit, preservation certification, or an independent backup commitment.</p><p>Consult the licence attached to the specific item or edition before reuse. Material reproduced inside a publication can carry separate third-party rights. No physical transfer, acquisition agreement, or original archival custody history is documented by this catalogue.</p><p>Item records provide preferred citations and metadata exports. For corrections, contact <a href="mailto:research@museumofone.art">research@museumofone.art</a> with the reference code and DOI.</p></section></div><section id="inventory" class="finding-inventory"><div class="section-head"><div><div class="section-no">Control / Description / Digital access</div><h2>Item inventory</h2></div><a class="text-link" href="metadata/inventory.csv" download>Download inventory · CSV ↓</a></div>'''
 rows=[]
 for group in groups:
  items=[r for r in records if r['collection']==group]
  content+=f'<section class="inventory-group"><h3>{E(group)}</h3><p>Editorial grouping · {len(items)} item records</p><div class="table-scroll"><table class="inventory-table"><caption class="sr-only">{E(group)} inventory</caption><thead><tr><th scope="col">Reference code</th><th scope="col">Title / description</th><th scope="col">Source date</th><th scope="col">Digital object</th></tr></thead><tbody>'
  for r in items:
   content+=f'<tr><th scope="row"><a href="items/{r["id"]}.html">{E(r["accession"])}</a></th><td><a href="items/{r["id"]}.html">{E(r["title"])}</a><small>{E(r["type"])} · {E(r["author"])}</small></td><td>{E(r["date"])}</td><td>'+(f'<a href="read/{r["id"]}.html">Read {r["page_count"]} pages ↗</a>' if r.get('reading_copy') else 'Source links in item record')+'</td></tr>'
   rows.append([r['accession'],r['title'],r['author'],r['date'],r['type'],r['collection'],r.get('page_count',''),r['doi'],r['zenodo_url']])
  content+='</tbody></table></div></section>'
 content+='</section><p class="finding-edition">Finding aid compiled from the selected source review dated 4 November 2026. Item descriptions and source statements govern over abbreviated inventory entries.</p>'
 write('finding-aid.html',layout('Finding aid','Collection-level guide, archival arrangement, access conditions and item inventory for the selected Museum of One corpus.',content,'finding-aid.html'))
 stream=io.StringIO();writer=csv.writer(stream);writer.writerow(['Local reference','Title','Creator','Source publication date','Resource type','Editorial arrangement','PDF file pages','Edition DOI','Repository record']);writer.writerows(rows);write('metadata/inventory.csv','\ufeff'+stream.getvalue())
